from Crypto.Util.number import getPrime, bytes_to_long, inverse
import random
flag = b"{REDACTED}"
m = bytes_to_long(flag)
p = getPrime(128)
q = getPrime(128)
n = p * q
phi = (p - 1) * (q - 1)
bound = int(n**0.25) // 9
d = random.randint(1, bound)
e = inverse(d, phi)

c = pow(m, e, n)
print(f"n = {n}")
print(f"e = {e}")
print(f"c = {c}")

